    await long_doc(tblhtml); s0 = await st(); await sel_block(SELT); await kb.press('Backspace'); await pg.wait_for_timeout(250); check('...con Retroceso', abs(await st() - s0) < 5, [s0, await st()])
    await long_doc(tblhtml); s0 = await st(); await sel_block(SELT); await pg.evaluate("document.querySelector('#bbar [data-b=\"del\"]').click()"); await pg.wait_for_timeout(250); check('...con el botón de papelera de la barra de bloques', abs(await st() - s0) < 5 and await pg.evaluate("ed.querySelectorAll('table').length") == 0, [s0, await st()])
    await long_doc(tblhtml); s0 = await st(); await sel_block(SELT); await kb.press('Control+x'); await pg.wait_for_timeout(250); check('...al cortar (Ctrl+X)', abs(await st() - s0) < 5, [s0, await st()])
    await long_doc(tblhtml); await sel_block(SELT); await kb.press('Delete'); await pg.wait_for_timeout(200); await kb.type('X'); pt = await pg.evaluate("[...ed.querySelectorAll('p')].find(p=>p.textContent.startsWith('X'))?.textContent")
    pt = await pg.evaluate("[...ed.querySelectorAll('p')].find(p=>p.textContent.startsWith('Después 1 '))?.textContent")
