    check('si el cursor queda fuera de la pantalla, manda lo que estás viendo (arriba: «Tres»)', await cur() == [2], await cur())
    await pg.evaluate("scroll.scrollTop = 0"); await pg.wait_for_timeout(200); check('...y al volver arriba, vuelve a «Uno»', await cur() == [0], await cur())
