    await doc_h(); await pg.evaluate("ed.blur(); getSelection().removeAllRanges(); (()=>{ const t=[...ed.querySelectorAll('h2')][0]; scroll.scrollTop = t.offsetTop - 10 })()"); await pg.wait_for_timeout(250); check('sin cursor en el documento (por ejemplo con bloques seleccionados) se guía por la posición', await cur() == [1], await cur())
    await doc_h(); await pg.evaluate("document.querySelectorAll('#olList .ol-item')[2].click()"); await pg.wait_for_timeout(150); check('clic en un encabezado del esquema: se marca al instante', await cur() == [2], await cur())
