    await doc_h("caretInto(ed.querySelectorAll('h2')[1], true)"); await kb.type(' nuevo'); await pg.wait_for_timeout(500); check('al editar el texto de un encabezado, el esquema se actualiza y mantiene la marca', await pg.evaluate("[...document.querySelectorAll('#olList .ol-item')][2].textContent") == 'Tres nuevo' and await cur() == [2], await cur())
    cs = await pg.evaluate("(()=>{ const a=getComputedStyle(document.querySelector('#olList .ol-item.cur')), n=getComputedStyle(document.querySelectorAll('#olList .ol-item:not(.cur)')[0]); return { cur: a.color, norm: n.color, bg: a.backgroundColor, weight: a.fontWeight, shadow: a.boxShadow } })()")
