    await pg.evaluate("h=>{ ed.innerHTML=h; ensureBlocks(); paintOutline(); }", '<p>Sin encabezados</p>'); await pg.wait_for_timeout(250); check('sin encabezados no falla ni marca nada', await cur() == [] and not errs, errs)
