    print('=== 3. «/comando» se vuelve código en línea ===')
    CODE = lambda t: f'<span data-code="">{t}</span>'
    async def typed(seq, html='<p><br></p>', caret=None):
      await fresh(html, caret or "caretInto(ed.firstElementChild, true)")
      for k in seq:
        if isinstance(k, tuple): await kb.press(k[0])
        else: await kb.type(k)
      return await dom()
